<?php if ($server['state'] === 'pending'): ?><details class="mt-3"><summary>Retry onboarding with fresh credentials</summary><form class="mt-3" method="post" action="/servers/bootstrap" autocomplete="off"><input type="hidden" name="_token" value="<?= $token ?>"><input type="hidden" name="server_id" value="<?= (int) $server['id'] ?>"><label class="form-label">Username<input class="form-control" name="username" value="root" required></label><label class="form-label">SSH password<input class="form-control" type="password" name="password" autocomplete="new-password" required></label><label class="form-label">Sudo password (if different)<input class="form-control" type="password" name="sudo_password" autocomplete="new-password"></label><button class="btn btn-primary btn-sm">Retry onboarding</button></form></details><?php endif; ?>
<?php if ($server['state'] === 'draining'): ?><form class="mt-3" method="post" action="/servers/action"><input type="hidden" name="_token" value="<?= $token ?>"><input type="hidden" name="server_id" value="<?= (int) $server['id'] ?>"><input type="hidden" name="action" value="deboard"><label class="form-check"><input class="form-check-input" type="checkbox" name="delegation_removed" value="yes" required><span class="form-check-label">This member has been removed from zone NS records, registrar delegation, and applicable glue.</span></label><label class="form-check mb-3"><input class="form-check-input" type="checkbox" name="ttl_elapsed" value="yes" required><span class="form-check-label">Delegation and record TTLs have elapsed.</span></label><button class="btn btn-danger btn-sm">Deboard & revoke automation access</button></form><?php endif; ?>
</div></article><?php endforeach; ?><?php if (!$servers): ?><div class="card"><div class="empty-state"><h2>No members connected</h2><p>Add servers in independent locations to build your DNS network.</p></div></div><?php endif; ?></section>
