<?php foreach (['name' => ['Member name', 'ns1-europe'], 'location' => ['Location', 'Frankfurt, Germany'], 'address' => ['SSH IP address', '192.0.2.10'], 'ssh_port' => ['SSH port', '22'], 'host_fingerprint' => ['Pinned host fingerprint', 'SHA256:…'], 'username' => ['Bootstrap username', 'root']] as $name => [$label, $placeholder]): ?><label class="form-label small w-100"><?= $label ?><input class="form-control" name="<?= $name ?>" placeholder="<?= $placeholder ?>" <?= $name === 'ssh_port' ? 'value="22" type="number" min="1" max="65535"' : '' ?> required></label><?php endforeach; ?>
